// dispatch/resolve.mjs — unit -> executor -> model/tier/command resolution
// (D7, tsk-2uf-1): `resolveTierModel`, the purpose/executorId resolution chain
// (`resolveExecutorAndOverrides`), and
// `resolveExecutorConfig` (the executor-block resolve + cross-provider
// governance gate `dispatch/transport.mjs`'s `resolveExecutorCommand`
// calls). Split out of the former `src/runner/dispatch.mjs` (2204 lines, 6
// concerns in one file) — pure move, no behavior change;
// `src/runner/dispatch.mjs` re-exports every name below unchanged as a
// barrel. See `docs/history/dispatch-activation-and-handoff-redesign/
// CONTEXT.md` D7 for the split rationale.

import { RunnerConfigError, EXECUTOR_CARRIES, CLAUDE_CLI_COMMANDS, MODEL_POLICY_TIERS, normalizePreferCandidates } from './config.mjs';
import { parseTierCell } from './tier-cell.mjs';
import { credentialStoreOf } from './provider-capacity.mjs';

/**
 * Canonical capability identity for a dispatch, independent of any Work item.
 * `hints` carries what the caller knows about what the dispatch is FOR:
 * extra candidate capability names, one capability to prefer when it is a
 * candidate, and a label to fall back to when nothing else resolves. A Work-driven
 * caller derives those from its Workflow step (src/runner/work-compat.mjs).
 *
 * Single, order-independent resolution rules: an explicit purpose wins; else a
 * candidate with required confinement, then any configured confinement, then the
 * preferred one, then a registered capability, then the first sorted candidate.
 */
export function resolveCapabilityDetailsFromHints({
  cfg,
  executorId,
  resolvedExecutor,
  purpose,
  hints,
} = {}) {
  const { candidates = [], preferred = null, fallbackLabel = null } = hints ?? {};
  const capabilities = cfg?.capabilities && typeof cfg.capabilities === 'object' ? cfg.capabilities : {};

  function resolveAlias(name) {
    if (!name || typeof name !== 'string') return name;
    if (capabilities[name]) return name;
    for (const [capName, capEntry] of Object.entries(capabilities)) {
      if (Array.isArray(capEntry?.aliases) && capEntry.aliases.includes(name)) {
        return capName;
      }
    }
    return name;
  }

  const explicitPurpose = purpose && typeof purpose === 'string' && purpose.trim()
    ? resolveAlias(purpose.trim())
    : null;

  const candidateSet = new Set(candidates);

  // A tool executor's declared capabilities (`for: [...]`). An agent executor
  // declares none: what it does is the dispatch's to say, never inferred here.
  if (resolvedExecutor?.kind === 'tool' && Array.isArray(resolvedExecutor.for)) {
    for (const f of resolvedExecutor.for) {
      if (typeof f === 'string' && f.trim()) {
        candidateSet.add(f.trim());
      }
    }
  }

  // Capabilities in config that `prefer` this executor
  if (executorId || resolvedExecutor) {
    for (const [capName, capEntry] of Object.entries(capabilities)) {
      if (capEntry?.prefer && (capEntry.prefer === executorId || (resolvedExecutor && cfg?.executors?.[capEntry.prefer] === resolvedExecutor))) {
        candidateSet.add(capName);
      }
    }
  }

  // Executor ID itself
  if (executorId && typeof executorId === 'string') {
    candidateSet.add(executorId);
  }

  // Normalize all candidates through aliases
  const normalizedCandidates = Array.from(candidateSet)
    .map((c) => resolveAlias(c))
    .filter(Boolean);

  let capability = explicitPurpose;
  if (!capability && normalizedCandidates.length === 0) {
    capability = fallbackLabel ?? executorId ?? '(unknown-capability)';
  }

  // 1. Any candidate with required confinement (confinement.mode === 'required') wins!
  const requiredCandidates = normalizedCandidates.filter(
    (c) => capabilities[c]?.confinement?.mode === 'required',
  );
  if (!capability && requiredCandidates.length > 0) {
    requiredCandidates.sort();
    capability = requiredCandidates[0];
  }

  // 2. Any candidate with configured confinement wins next
  const configuredConfinementCandidates = normalizedCandidates.filter(
    (c) => Boolean(capabilities[c]?.confinement),
  );
  if (!capability && configuredConfinementCandidates.length > 0) {
    configuredConfinementCandidates.sort();
    capability = configuredConfinementCandidates[0];
  }

  // 3. The caller's preferred capability, when it is a candidate
  if (!capability && preferred && normalizedCandidates.includes(preferred)) {
    capability = preferred;
  }

  // 4. Prefer registered capabilities in cfg.capabilities
  const registeredCandidates = normalizedCandidates.filter((c) => Boolean(capabilities[c]));
  if (!capability && registeredCandidates.length > 0) {
    registeredCandidates.sort();
    capability = registeredCandidates[0];
  }

  // 5. Fallback: sorted candidates first.
  if (!capability) {
    normalizedCandidates.sort();
    capability = normalizedCandidates[0];
  }

  const policyAnchors = normalizedCandidates
    .filter((candidate) => candidate !== capability && capabilities[candidate]?.confinement);
  const requiredAnchors = policyAnchors.filter(
    (candidate) => capabilities[candidate]?.confinement?.mode === 'required',
  ).sort();
  const anchorCapability = requiredAnchors[0] ?? policyAnchors.sort()[0] ?? null;

  return { capability, anchorCapability };
}

/**
 * Every entry of the cell cfg.modelPolicies[provider][tier], in order, as
 * `{model, pool, explicitPool}` (see `parseTierCell`), whichever pool serves
 * them: each is a candidate of the seat's walk.
 * Valid tiers: nano | mini | standard | advanced | flagship | frontier.
 */
export function resolveTierCandidates(cfg, tier, provider = 'claude') {
  if (!MODEL_POLICY_TIERS.includes(tier)) {
    throw new RunnerConfigError(`unrecognized tier "${tier}". Valid tiers: [${MODEL_POLICY_TIERS.join(', ')}]`);
  }
  const policies = cfg && cfg.modelPolicies;
  if (!policies || typeof policies !== 'object') {
    throw new RunnerConfigError(`no modelPolicies configured.`);
  }
  const providerPolicy = policies[provider];
  if (!providerPolicy || typeof providerPolicy !== 'object') {
    throw new RunnerConfigError(`no modelPolicies configured for provider "${provider}".`);
  }
  const cell = providerPolicy[tier];
  if (cell === undefined) {
    throw new RunnerConfigError(`no model configured for tier "${tier}" under provider "${provider}".`);
  }
  try {
    return parseTierCell(cell, provider);
  } catch (err) {
    throw new RunnerConfigError(`no model configured for tier "${tier}" under provider "${provider}": ${err.message}.`);
  }
}

/** What a seat that needs a model is told when its family has no cell at the tier it runs at. */
export function tierCellMissingDetail(family, tier) {
  return `no model for tier "${tier}" under family "${family}" (runner.modelPolicies.${family}.${tier})`;
}

/**
 * The families `cfg.tierFallback.<tier>` declares as the walk order for a seat that failed at `tier`, or
 * null when the tier declares none (the walk then follows the capability's `prefer` order).
 */
export function tierFallbackOf(cfg, tier) {
  const families = cfg?.tierFallback?.[tier];
  return Array.isArray(families) ? [...families] : null;
}

/**
 * Resolve a tier to the model name the provider family runs first: the model of the first entry of
 * cfg.modelPolicies[provider][tier], whichever pool serves it (the primary candidate of the seat's
 * walk). Callers that need the pool, or whether the pool can serve the call, read the candidates:
 * bind() expands every entry and drops the ones whose pool is unusable.
 */
export function resolveTierModel(cfg, tier, provider = 'claude') {
  return resolveTierCandidates(cfg, tier, provider)[0].model;
}

/**
 * Derive a executor's PROVIDER FAMILY (tsk-2uf-1, Phase 00 R6, fixes H2a):
 * the executor's own declared `providerModel` field wins, then `provider`,
 * then a Claude-CLI-command inference, then the resolved command literal
 * itself. Extracted (pure move, byte-identical for every existing caller)
 * from `resolveExecutorConfig`'s own inline derivation below so a second
 * caller (`assignment-policy.mjs`'s pre-spawn policy resolution, which has
 * no resolved `executor.command` yet) reads the SAME rule instead of a
 * third, independently-drifting copy of it — `resolvedCommand` defaults to
 * `'claude'` for that caller, which resolves through the
 * `CLAUDE_CLI_COMMANDS` branch to `'claude'`, matching R6's own simpler
 * rule ("default to claude only when the executor is registered but names
 * no providerModel of its own").
 */
export function deriveProviderFamily(executorEntry, resolvedCommand = 'claude') {
  return typeof executorEntry?.providerModel === 'string' && executorEntry.providerModel.trim()
    ? executorEntry.providerModel
    : typeof executorEntry?.provider === 'string' && executorEntry.provider.trim()
      ? executorEntry.provider
      : CLAUDE_CLI_COMMANDS.includes(resolvedCommand)
        ? 'claude'
        : resolvedCommand;
}

/**
 * Resolve which executor block applies for `tier`/`executorId` (P41/D
 * a4fe4c2b, generalized executor-aware, D4/D6 tsk-62v). Precedence (D4;
 * tsk-in1-2 D6 retired the intermediate `executors.<tier>` rung — 0 live
 * entries, had already caused a real bug per tsk-5tm D10):
 * `executors.<executorId>` (only when that entry declares its own
 * `command`/`adapter` — a executor entry naming neither is metadata-only
 * and falls through) > `executor` (global). No `executorId` given at all
 * keeps every pre-tsk-62v call site's behavior identical.
 *
 * A `executors.<executorId>` entry naming no `command`/`adapter` of its
 * own but declaring `agentType` (D1/D2, tsk-3sw) resolves via
 * `buildAgentTypeExecutor` instead of falling all the way through to
 * `executor` (global) — still ahead of that fallback in the same
 * precedence slot `command`/`adapter` already occupy.
 *
 * Presence/staleness of a `executors.<executorId>` entry's own tool is no
 * longer checked here (tsk-5tm-1 D1: retired — 2/3 real entries were
 * `kind:"task"`, for which this never ran, and the third's `needs` added no
 * signal beyond the OS's own ENOENT on a missing binary). Ask `fgos tool
 * query --status present/stale` directly at the call site instead.
 *
 * Cross-provider governance (D2/D3, tsk-32n): once the winning `executor`
 * is resolved below, a `kind: "cli"` executor whose FINAL resolved
 * `command` is not in `CLAUDE_CLI_COMMANDS` requires
 * `executor.allowCrossProvider === true` — absent or `false` throws
 * `RunnerConfigError` here, before any dispatch. Checked on the resolved
 * `command` (never on `executor.kind` alone, and never on `provider`): a
 * `kind: "cli"` executor naming no `command`/`adapter` of its own falls
 * through to `executor` (global, D4 above), ordinarily Claude's
 * own CLI — gating on declared `kind` alone would false-positive that
 * case, and `provider` is a freely-overridable display alias, not the
 * command actually spawned.
 */
/**
 * Derive a real, spawnable executor block for a `kind:"task"` executor that
 * declares only `agentType` (no own `command`/`args`) — D1/D2, tsk-3sw,
 * Claude-only for now (this item's own `CONTEXT.md`: multi-provider
 * `agentType` support is `tsk-53h`'s separate follow-on, not built here).
 * Reuses `baseExecutor`'s (the already-resolved `cfg.executor`, guaranteed
 * `{command,args}`-shaped by `validateExecutorShape` at config-load time)
 * own args template verbatim — never a hardcoded literal copy of
 * `DEFAULT_RUNNER_CONFIG` — so a project's own `--allowedTools`/
 * `--permission-mode` customization carries through to its agentType
 * executors too. Strips the `'--model','{model}'` pair (D2: the named
 * agent definition's own pinned `model:` frontmatter wins, never overridden
 * by the work item's `tier`) and appends `'--agent', agentType`.
 */
function buildAgentTypeExecutor(baseExecutor, agentType) {
  const args = [];
  for (let i = 0; i < baseExecutor.args.length; i++) {
    if (baseExecutor.args[i] === '--model' && baseExecutor.args[i + 1] === '{model}') {
      i++; // also skip the paired value token
      continue;
    }
    args.push(baseExecutor.args[i]);
  }
  args.push('--agent', agentType);
  return { command: baseExecutor.command, args };
}

/**
 * Resolve a `executorId`-OR-purpose name to its real serving executor,
 * applying `capabilities.<name>.prefer`/`overrides` (2026-08-16 user
 * decision, `docs/decisions/0033-...md`'s sibling `docs/history/
 * capability-capacity-remodel/CONTEXT.md` D1/D2) — the ONE place every
 * `cfg.executors[executorId]` lookup in this file should go through
 * instead of tracing it out ad hoc (D4: `spawnWorker` used to have its
 * own separate inline lookup for model resolution, distinct from
 * `resolveExecutorConfig`'s own internal one — fixing only one left them
 * resolving inconsistently after a duplicate `executors.<id>` entry is
 * removed in favor of `for`/`prefer`).
 *
 * Order (D1): (1) a literal `cfg.executors[executorIdOrPurpose]` entry
 * always wins first, unchanged from every pre-this-item caller's own
 * behavior — this is the deep-customization escape-hatch (a different
 * `command`/`args` entirely), never touched by `overrides`. (2) failing
 * that, `cfg.capabilities[executorIdOrPurpose].prefer` names a real
 * registered executor directly — no requirement that the executor also
 * self-declare a matching `for` entry (D5, `docs/history/capability-
 * capacity-remodel/CONTEXT.md`, supersedes D2's own symmetry requirement:
 * the reverse check forced a second config edit per wiring decision
 * without a proportional safety benefit — a careless `prefer` edit could
 * add a careless `for` entry just as easily). `prefer` naming an executor
 * id that does not exist at all still throws loud (`RunnerConfigError`),
 * matching every other shape-validation gate in this file. (3) nothing
 * found — `{executorId: null, configured: false}`, a legitimate,
 * expected state, never thrown. An executor's own `for` never binds a
 * purpose here: only `capabilities.<name>.prefer` does.
 *
 */
export function resolveExecutorAndOverrides(cfg, executorIdOrPurpose) {
  const executors = cfg && cfg.executors && typeof cfg.executors === 'object' ? cfg.executors : {};
  if (executors[executorIdOrPurpose]) {
    return { executorId: executorIdOrPurpose, executor: executors[executorIdOrPurpose], configured: true, bindingSource: 'executor-id' };
  }
  if (!executorIdOrPurpose && cfg?.executor) {
    return { executorId: cfg.executor.command ?? 'executor', executor: cfg.executor, configured: true, bindingSource: 'default' };
  }
  if (cfg?.executor && (executorIdOrPurpose === 'executor' || executorIdOrPurpose === cfg.executor.command || executorIdOrPurpose === cfg.executor.invocations?.[0]?.command || executorIdOrPurpose === cfg.executor.invocations?.[0]?.id)) {
    return { executorId: executorIdOrPurpose, executor: cfg.executor, configured: true, bindingSource: 'default' };
  }
  const capabilityEntry = cfg && cfg.capabilities && typeof cfg.capabilities === 'object' ? cfg.capabilities[executorIdOrPurpose] : undefined;
  const preferred = capabilityEntry?.prefer;
  if (preferred !== undefined) {
    // executor-id-consolidation Step 2.2: `prefer` may now be a single
    // string (legacy, unchanged) or an ORDERED candidate array (cascade,
    // account-rotator-style — try candidates[0], fall to the next only
    // when it is not usable). `normalizePreferCandidates` always returns
    // an array; the single-string case becomes its own 1-element array,
    // so `candidates[0]` is exactly the pre-existing `preferred` value for
    // every config that has not adopted the array shape — zero behavior
    // change for every currently-configured capability.
    const candidates = normalizePreferCandidates(preferred, `capabilities.${executorIdOrPurpose}.prefer`);
    const primary = candidates[0];
    const executor = executors[primary.executor];
    if (!executor) {
      throw new RunnerConfigError(
        `runner config capabilities.${executorIdOrPurpose}.prefer names "${primary.executor}" but no such executor is registered.`,
      );
    }
    return {
      executorId: primary.executor,
      executor,
      configured: true,
      bindingSource: 'capability.prefer',
      invocationId: primary.invocation,
      candidates,
    };
  }
  return { executorId: null, executor: undefined, configured: false, bindingSource: null };
}

// Exported (additive, D7 module split): `dispatch/transport.mjs`'s
// `resolveExecutorCommand` calls this cross-module now that it lives in a
// sibling file — was a bare same-file `function` before the split
// (byte-identical value/behavior, only newly reachable from outside this
// file).
export function resolveExecutorConfig(cfg, tier, executorId, fgosDir, contentCarries, resolvedAgentType, invocationId) {
  const resolved = executorId ? resolveExecutorAndOverrides(cfg, executorId) : undefined;
  const executorEntry = resolved?.executor;
  // Self-review finding: `executorId` below is the CALLER's own requested
  // id/purpose (e.g. "fgos-coding-implement"), never rewritten to the
  // executor `prefer` actually resolved (e.g. "agy") -- every error
  // message already citing `executorId` stays worded exactly as before
  // (zero risk to existing message-text expectations), but the
  // `allowCrossProvider` remediation line is the one place an imprecise
  // id gives actively WRONG advice ("set executors.fgos-coding-
  // implement.allowCrossProvider" -- not a real executors key at all
  // when resolved via `prefer`), so that one message names the real
  // resolved id too when it differs.
  const realExecutorId = resolved?.executorId;

  // D15/tsk-5td, first real gate — carries answers "CAI GI duoc di", never
  // "CO duoc ra ngoai khong" (allowCrossProvider's own question, checked
  // separately below): when the executor declares a content-permission
  // class, the caller must self-declare what THIS dispatch actually
  // carries (`contentCarries`) — fail closed (never silently allow) when
  // the executor opts into this gate but the caller passes nothing, since
  // there is then no way to prove the dispatch is safe. `repo-content` is
  // the wider, riskier class (it covers `user-text` plus repo paths/
  // content); a executor declaring `carries: "user-text"` refuses a
  // `repo-content` dispatch before any spawn (verify item 8, tsk-2c1) —
  // a executor declaring `carries: "repo-content"` accepts either.
  if (executorEntry && executorEntry.carries !== undefined) {
    if (contentCarries === undefined) {
      throw new RunnerConfigError(
        `executor "${executorId}" declares "carries: ${executorEntry.carries}" but this dispatch did not declare what content it carries — pass an explicit content class before dispatch.`,
      );
    }
    if (!EXECUTOR_CARRIES.includes(contentCarries)) {
      throw new RunnerConfigError(
        `dispatch content class must be one of ${EXECUTOR_CARRIES.join('/')}, got: ${JSON.stringify(contentCarries)}.`,
      );
    }
    if (contentCarries === 'repo-content' && executorEntry.carries === 'user-text') {
      throw new RunnerConfigError(
        `executor "${executorId}" declares "carries: user-text" but this dispatch carries repo-content — refused before spawn (tsk-5td D15).`,
      );
    }
  }

  // tsk-5tm-4 D11: an invocations[]-shaped executor resolves through its
  // own invocation, ahead of the flat command/args check below — real
  // entries declare one shape or the other, never both, but invocations[]
  // wins on the (currently hypothetical) case they do.
  //
  // Gate B2 (D9, tsk-in1-4): select the invocation whose `via` is `"cli"`
  // specifically — never blindly `invocations[0]` — since `cli-spawn` is
  // the only mechanism this function ever actually dispatches through; a
  // executor declaring, say, `[{via:"mcp",...}, {via:"cli",...}]` must
  // still resolve the cli one regardless of array order.
  //
  // executor-id-consolidation Step 2.1: an executor can declare MULTIPLE
  // `via:"cli"` invocations (e.g. a full-write default alongside a
  // read-only/confined variant) — Gate B2's original "first cli match"
  // pick cannot distinguish between them at all. `invocationId`, when
  // passed, names exactly which one; the explicit caller param (this
  // function's own last argument, used by the read-only-redirect and
  // capability.prefer callers, see resolveExecutorAndOverrides) always
  // wins over `resolved.invocationId` (an id threaded through by
  // resolveExecutorAndOverrides's own capability.prefer resolution below).
  // Neither is ever passed by any pre-existing caller, so this is
  // additive-only: every caller that never names an invocation id keeps
  // the exact same "first via:cli" pick as before.
  const requestedInvocationId = invocationId ?? resolved?.invocationId;
  //
  // Gate B3 (D9, tsk-in1-4): when `invocations` IS present but none of
  // them is `via:"cli"` (e.g. `gitnexus`'s mcp-only entry), that is a
  // executor structurally incapable of being dispatched this way — throw
  // explicitly rather than falling through to the global executor as if
  // the executor were merely metadata-only. Silently spawning the global
  // Claude executor in gitnexus's name would hide exactly the kind of
  // caller mistake this gate exists to catch ("bẫy B1" from shaping:
  // an mcp identifier misread as a spawnable command).
  const invocations = Array.isArray(executorEntry?.invocations) ? executorEntry.invocations : undefined;
  const cliInvocation = requestedInvocationId
    ? invocations?.find((inv) => inv.id === requestedInvocationId && inv.via === 'cli')
    : invocations?.find((inv) => inv.via === 'cli');
  if (invocations && !cliInvocation) {
    throw new RunnerConfigError(
      requestedInvocationId
        ? `executor "${executorId}" has no "invocations" entry with "id": "${requestedInvocationId}" dispatchable via "cli" (has: ${invocations.map((inv) => `${inv.id ?? '(no id)'}:${inv.via}`).join(', ')}).`
        : `executor "${executorId}" declares "invocations" but none is dispatchable via "cli" (has: ${invocations.map((inv) => inv.via).join('/')}) — resolveExecutorConfig only ever spawns a cli invocation; this executor cannot be dispatched this way.`,
    );
  }
  // D15/D20/D22 (review finding H1, tsk-397): `executorEntry.agentType`
  // (an executor's own static config) always wins first when set --
  // `resolvedAgentType` (the caller's D20 eligibility-inversion result,
  // resolveAgentTypeForTaskSpec via src/runner/agent-roster.mjs) only
  // ever fills in when the executor declares NONE of its own, so this
  // stays additive: an executor that already names a real agentType is
  // completely unaffected, and every executor with its own command/args/
  // invocations (agy, claude, codex, pi -- every real executor this repo
  // configures today) never reaches this branch at all regardless of
  // what resolvedAgentType is, since `resolvedViaAgentType` below already
  // requires a command-less, invocation-less entry.
  const effectiveAgentType = executorEntry?.agentType ?? resolvedAgentType;
  const resolvedViaAgentType = !cliInvocation && !(executorEntry && (executorEntry.adapter || executorEntry.command)) && Boolean(effectiveAgentType && cfg && cfg.executor);
  let defaultCliInvocation = null;
  if (!executorEntry && cfg?.executor?.invocations) {
    defaultCliInvocation = cfg.executor.invocations.find((inv) => inv.via === 'cli');
  }
  const byExecutor = cliInvocation
    ? { command: cliInvocation.command, args: cliInvocation.args, adapter: cliInvocation.adapter, provider: executorEntry?.provider, env: cliInvocation.env ?? executorEntry?.env, liveOutput: cliInvocation.liveOutput ?? executorEntry?.liveOutput, interactiveMode: cliInvocation.interactiveMode ?? executorEntry?.interactiveMode, promptDelivery: cliInvocation.promptDelivery ?? executorEntry?.promptDelivery, permissionMode: cliInvocation.permissionMode ?? executorEntry?.permissionMode, confinement: cliInvocation.confinement ?? executorEntry?.confinement, credentialStore: credentialStoreOf({ command: cliInvocation.command, credentialStore: cliInvocation.credentialStore, resourceBindings: cliInvocation.resourceBindings ?? executorEntry?.resourceBindings }) }
    : executorEntry && (executorEntry.adapter || executorEntry.command)
      ? executorEntry
      : defaultCliInvocation
        ? { command: defaultCliInvocation.command, args: defaultCliInvocation.args, adapter: defaultCliInvocation.adapter, provider: cfg?.executor?.provider, env: defaultCliInvocation.env ?? cfg?.executor?.env, liveOutput: defaultCliInvocation.liveOutput ?? cfg?.executor?.liveOutput, interactiveMode: defaultCliInvocation.interactiveMode ?? cfg?.executor?.interactiveMode, promptDelivery: defaultCliInvocation.promptDelivery ?? cfg?.executor?.promptDelivery, permissionMode: defaultCliInvocation.permissionMode ?? cfg?.executor?.permissionMode, confinement: defaultCliInvocation.confinement ?? cfg?.executor?.confinement, credentialStore: credentialStoreOf({ command: defaultCliInvocation.command, credentialStore: defaultCliInvocation.credentialStore, resourceBindings: defaultCliInvocation.resourceBindings ?? cfg?.executor?.resourceBindings }) }
        : resolvedViaAgentType
          ? buildAgentTypeExecutor(cfg.executor, effectiveAgentType)
          : undefined;
  const executor = byExecutor ?? (cfg && cfg.executor);
  if (!executor || typeof executor.command !== 'string' || !Array.isArray(executor.args)) {
    throw new RunnerConfigError('runner config "executor" must have a string "command" and an "args" array.');
  }

  // Declared egress & Cross-provider governance (D1/D2/D6):
  // Inspect providerFamily and effective egress {kind, target, content}.
  // An env override (e.g. ANTHROPIC_BASE_URL, OPENAI_BASE_URL, BASE_URL)
  // or a non-Claude command/provider routes egress to a cross-provider backend.
  const envBlock = executor.env ?? cliInvocation?.env ?? executorEntry?.env;
  const envTarget = envBlock?.ANTHROPIC_BASE_URL || envBlock?.OPENAI_BASE_URL || envBlock?.BASE_URL;
  // Security review finding (self-review, 2026-08-25): a substring check
  // (`envTarget.includes('api.anthropic.com')`) is bypassable by any URL
  // that merely CONTAINS that literal text anywhere — a path segment
  // (`https://evil.example.com/api.anthropic.com`), a query param, or a
  // subdomain-lookalike host all read as "same-provider" under a substring
  // test, silently clearing the cross-provider gate this check exists to
  // enforce. Real hostname comparison, fail-closed: an unparseable URL is
  // never trusted as "still Anthropic" — it counts as an override, same as
  // any other non-matching host.
  const isAnthropicApiHost = (urlString) => {
    try {
      const { hostname } = new URL(urlString);
      return hostname === 'api.anthropic.com' || hostname.endsWith('.api.anthropic.com');
    } catch {
      return false;
    }
  };
  const isEnvUrlOverride = typeof envTarget === 'string' && envTarget.trim().length > 0 && !isAnthropicApiHost(envTarget);

  const providerFamily = deriveProviderFamily(executorEntry, executor.command);

  const egressTarget = isEnvUrlOverride ? envTarget : executor.command;

  const isCrossProvider =
    isEnvUrlOverride ||
    !CLAUDE_CLI_COMMANDS.includes(executor.command) ||
    (executorEntry?.providerModel !== undefined && executorEntry.providerModel !== 'claude');

  const egressKind = isCrossProvider ? 'cross-provider' : 'same-provider';
  const egressContent = executorEntry?.carries ?? contentCarries ?? 'repo-content';

  const governance = {
    providerFamily,
    egress: {
      kind: egressKind,
      target: egressTarget,
      content: egressContent,
    },
  };

  if (executorEntry && !resolvedViaAgentType && egressKind === 'cross-provider' && executorEntry.allowCrossProvider !== true) {
    const remediationId = realExecutorId && realExecutorId !== executorId ? realExecutorId : executorId;
    const resolvedNote = realExecutorId && realExecutorId !== executorId ? ` (resolved via capabilities."${executorId}".prefer to executor "${realExecutorId}")` : '';
    throw new RunnerConfigError(
      `executor "${executorId}"${resolvedNote} resolves to cross-provider egress target "${egressTarget}" — prompt content would leave the Claude ecosystem. Set executors.${remediationId}.allowCrossProvider: true to permit this.`,
      { code: 'governance.cross-provider-not-permitted' },
    );
  }

  return {
    ...executor,
    // The executor's declared capabilities (e.g. which reasoningEffort levels
    // it accepts) live on the entry, not on the invocation picked above.
    ...(executorEntry?.supports && !executor.supports ? { supports: executorEntry.supports } : {}),
    governance,
  };
}

/**
 * executor-id-consolidation Step 2 (fallback confinement preservation): the
 * first `via:"cli"` invocation on `executorEntry` whose EFFECTIVE
 * confinement (its own, or inherited from the executor entry -- the exact
 * same `cliInvocation.confinement ?? executorEntry.confinement` fallback
 * Gate B2's own `byExecutor` construction above already applies) is a
 * non-empty object. Returns `undefined` when the executor has no
 * `invocations[]` at all, or none of them declare any confinement.
 *
 * This is a STRUCTURAL check only ("is anything declared for Confinement
 * Authority to enforce"), never a semantic one ("does it satisfy policy
 * X") -- that verification is Confinement Authority's own job
 * (`confinement/authority.mjs`), already a large, separate subsystem this
 * function does not reach into. The one rule this enforces, mirroring
 * `validateOverrideConfinementShape`'s own documented invariant ("override
 * can only harden posture... downgrades are rejected"): a caller
 * substituting one executor for another (e.g. a provider-capacity
 * fallback) must never silently trade a confined primary for an
 * unconfined substitute.
 */
export function selectConfinedInvocationId(executorEntry) {
  const invocations = Array.isArray(executorEntry?.invocations) ? executorEntry.invocations : undefined;
  if (!invocations) return undefined;
  const confined = invocations.find((inv) => {
    if (inv.via !== 'cli') return false;
    const effective = inv.confinement ?? executorEntry.confinement;
    return effective && typeof effective === 'object' && Object.keys(effective).length > 0;
  });
  return confined?.id;
}

// dispatch/run-lock.mjs — the one append-only generation/release-marker
// primitive this cell introduces, per
// plans/260911-2305-runtime-recovery/phase-designs/run-admission-and-fencing.md
// ("Lock Protocol") and
// docs/architect/agent-coordination/architecture/runtime-recovery-design.md
// section 6 ("Local Concurrency And Durability").
//
// Shared by three callers: Assignment/Run admission (assignment-runner.mjs),
// schema-2 session retry declarations (coordination/store.mjs), and per-Run
// control-epoch/token fencing (this file's own acquireRunControl/
// releaseRunControl). One scope directory holds immutable, monotonically
// numbered generation records plus token-specific release markers, both
// published by a fsynced temp file followed by an exclusive hard link.
// Nothing here ever unlinks or overwrites a published record: a delayed
// straggler can only ever publish a NEW, higher-numbered generation, never
// touch an earlier one, so a stale release can never delete a successor.
//
// Reclaim rule (the fact P00 corrected against main-checkout-lock.mjs's own
// heartbeat-mitigated TTL takeover): a live PID remains HELD no matter how
// stale its heartbeat looks. `ttlMs` only gates whether a contender bothers
// to probe process liveness at all; the actual reclaim decision is PID-dead
// proof (`isProcessAlive` returns false), never elapsed time alone.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { getBootId, getProcessStartTime, resolveHolderLiveness as resolveHolderLivenessByIdentity } from './process-identity.mjs';

// --- PID liveness --------------------------------------------------------

/** Signal-0 liveness probe (mirrors main-checkout-lock.mjs's isPidAlive).
 * EPERM means the pid exists under another user -- still alive. */
export function isProcessAlive(pid) {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (err) {
    return err.code === 'EPERM';
  }
}

// --- Control holder identity (H1) -----------------------------------------

/** Build a control holder identity for the CURRENT process: `{id, pid,
 * bootId, processStartTime, host}`. Centralizes the shape so every
 * acquireRunControl caller records the same cross-checkable identity --
 * `id` alone (the pre-H1 shape) let a PID reused by an unrelated process
 * after the real holder died be mistaken for the same holder. */
export function buildRunControlHolder(id) {
  return {
    id,
    pid: process.pid,
    bootId: getBootId(),
    processStartTime: getProcessStartTime(process.pid),
    host: os.hostname(),
  };
}

/** Whether a recorded control holder is still the live process that
 * acquired the lock. Thin backward-compatible wrapper (dispatch-engine-
 * liveness-hardening Phase 1): the actual bootId/processStartTime judge now
 * lives in process-identity.mjs as a pure function taking an injected
 * liveness fact, so it can be reused without pulling `process.kill` (this
 * file's own control-plane probe, `isProcessAlive`) into that fs-only leaf.
 * Full decision-table doc lives on process-identity.mjs's own
 * resolveHolderLiveness. */
export function resolveHolderLiveness(holder) {
  return resolveHolderLivenessByIdentity(holder, isProcessAlive(holder?.pid));
}

// --- Fsynced atomic publication -------------------------------------------

function writeFsyncedTemp(dir, content) {
  const tmpPath = path.join(dir, `.tmp-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const fd = fs.openSync(tmpPath, 'w');
  try {
    fs.writeSync(fd, content);
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }
  return tmpPath;
}

/** Best-effort fsync of an already-written file, for a caller that wrote it
 * via plain `fs.writeFileSync` rather than `writeFsyncedTemp` above (e.g. a
 * file inside a staging directory this module doesn't own the writing of). */
export function fsyncFileBestEffort(filePath) {
  let fd;
  try {
    fd = fs.openSync(filePath, 'r+');
    fs.fsyncSync(fd);
  } catch {
    // best-effort, mirrors fsyncDirBestEffort below
  } finally {
    if (fd !== undefined) {
      try {
        fs.closeSync(fd);
      } catch {
        // ignore
      }
    }
  }
}

export function fsyncDirBestEffort(dir) {
  let fd;
  try {
    fd = fs.openSync(dir, 'r');
    fs.fsyncSync(fd);
  } catch {
    // Some platforms/filesystems refuse to open a directory for fsync;
    // publication already happened via the hard link itself, so this is
    // best-effort durability, not the correctness boundary.
  } finally {
    if (fd !== undefined) {
      try {
        fs.closeSync(fd);
      } catch {
        // ignore
      }
    }
  }
}

function removeTempBestEffort(tmpPath) {
  try {
    fs.unlinkSync(tmpPath);
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
}

// --- Generic append-only generation ledger --------------------------------
//
// A directory of immutable, monotonically numbered JSON records. Contenders
// for the same next generation race on one target path; exactly one wins
// the exclusive hard link, every loser rereads the (now different) current
// generation and re-decides.

const GENERATION_FILE_RE = /^(\d{10})\.json$/;

function generationFileName(epoch) {
  return `${String(epoch).padStart(10, '0')}.json`;
}

function parseJsonFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw err;
  }
  try {
    return JSON.parse(raw);
  } catch {
    // A record this primitive published is always complete (fsynced temp +
    // atomic link); unparseable content here can only mean something else
    // wrote into this directory. Treated as absent, never authoritative.
    return null;
  }
}

/** Every published generation record in `generationsDir`, ascending by
 * epoch. Missing directory reads as an empty ledger. */
export function listGenerations(generationsDir) {
  let names;
  try {
    names = fs.readdirSync(generationsDir);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  const records = [];
  for (const name of names) {
    const match = GENERATION_FILE_RE.exec(name);
    if (!match) continue;
    const record = parseJsonFile(path.join(generationsDir, name));
    if (record === null) continue;
    records.push({ epoch: Number(match[1]), record });
  }
  records.sort((a, b) => a.epoch - b.epoch);
  return records;
}

/** The highest-epoch published generation, or null when the ledger is
 * empty. Never a cached/rebuilt projection -- always a fresh directory
 * read, since a rebuildable projection is explicitly not authority here. */
export function currentGeneration(generationsDir) {
  const generations = listGenerations(generationsDir);
  return generations.length > 0 ? generations[generations.length - 1] : null;
}

/**
 * Attempt to publish the next generation in `generationsDir`.
 *
 * `decide({ current, nextEpoch, generations })` is called fresh on every
 * attempt (including after losing a race) and must return either:
 *   - `{ stop: true, ...rest }` -- do not publish anything; `rest` is
 *     returned verbatim alongside `{ published: false }` (e.g. recognizing
 *     an already-committed idempotent match, or refusing as stale/held).
 *   - `{ record }` -- attempt to publish `record` as generation `nextEpoch`.
 *
 * On a lost race (a concurrent contender already published `nextEpoch`),
 * this rereads the ledger and calls `decide` again against the new current
 * generation -- so a loser either recognizes the winner's record as its own
 * outcome, or contends again for the generation beyond it. Nothing here
 * ever unlinks or overwrites a published record.
 */
export function publishNextGeneration(generationsDir, decide) {
  fs.mkdirSync(generationsDir, { recursive: true });
  for (;;) {
    const generations = listGenerations(generationsDir);
    const current = generations.length > 0 ? generations[generations.length - 1] : null;
    const nextEpoch = (current?.epoch ?? 0) + 1;
    const decision = decide({ current, nextEpoch, generations });
    if (decision.stop) {
      return { published: false, ...decision };
    }

    const targetPath = path.join(generationsDir, generationFileName(nextEpoch));
    const tmpPath = writeFsyncedTemp(generationsDir, JSON.stringify(decision.record));
    try {
      fs.linkSync(tmpPath, targetPath);
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
      removeTempBestEffort(tmpPath);
      continue; // lost the race -- reread and let `decide` re-evaluate
    }
    removeTempBestEffort(tmpPath);
    fsyncDirBestEffort(generationsDir);
    return { published: true, epoch: nextEpoch, record: decision.record };
  }
}

// --- One-shot markers (release markers, abort markers, ...) --------------
//
// Same publication discipline as a generation record, but keyed by an
// explicit path rather than "next number" -- used for anything that is
// published at most once for a given key (a release marker for one
// control token, a fulfillment/abort marker for one retryId). Idempotent:
// a second publish for the same path is a no-op, never an overwrite.

export function publishMarkerOnce(markerPath, record) {
  const dir = path.dirname(markerPath);
  fs.mkdirSync(dir, { recursive: true });
  const tmpPath = writeFsyncedTemp(dir, JSON.stringify(record));
  try {
    fs.linkSync(tmpPath, markerPath);
  } catch (err) {
    if (err.code !== 'EEXIST') throw err;
    removeTempBestEffort(tmpPath);
    return { published: false };
  }
  removeTempBestEffort(tmpPath);
  fsyncDirBestEffort(dir);
  return { published: true };
}

/** Read a marker published by `publishMarkerOnce`. A `finally` marker is
 * evidence of a clean release, never death proof: callers must never treat
 * an ABSENT marker as "still alive" or "definitely dead" -- absence proves
 * nothing either way. */
export function readMarker(markerPath) {
  return parseJsonFile(markerPath);
}

// --- Per-Run control epoch/token fencing ----------------------------------

export function controlDirs(runDir) {
  const base = path.join(runDir, 'control');
  return { generationsDir: path.join(base, 'generations'), releasesDir: path.join(base, 'releases') };
}

function releaseMarkerPath(releasesDir, epoch) {
  return path.join(releasesDir, `${generationFileName(epoch)}.release`);
}

/**
 * Acquire per-Run control: a monotonic `controlEpoch` plus a unique
 * `controlToken`, fencing successive controller acquisitions of the same
 * Run (AD-02, AD-10). No async adapter call may run inside this function --
 * it is synchronous, fs-only, and returns before any I/O the caller does
 * with the acquired token.
 *
 * `holder` is `{ id, pid }`. `expectedControlEpoch`, when supplied, fences a
 * caller that read a stale epoch: if the Run's committed current epoch does
 * not match, this refuses with `status: 'stale'` without attempting
 * anything. `ttlMs` only gates whether a contender bothers to probe the
 * current holder's process liveness at all (an efficiency guard against
 * probing a healthy holder on every contention) -- omitting it means every
 * call probes. The actual reclaim decision is always PID-dead proof: a live
 * `holder.pid` (per `isProcessAlive`) is HELD regardless of how stale the
 * recorded generation looks. A `finally` release marker is evidence of a
 * clean release; its absence never proves the holder crashed and is never
 * treated as such.
 *
 * Returns `{ status: 'acquired', controlEpoch, controlToken }`,
 * `{ status: 'held', controlEpoch, holder }`, or
 * `{ status: 'stale', controlEpoch }` (the ambient current epoch, which
 * disagreed with `expectedControlEpoch`).
 */
export function acquireRunControl(runDir, { holder, purpose, expectedControlEpoch, ttlMs, now = Date.now() } = {}) {
  const { generationsDir, releasesDir } = controlDirs(runDir);

  const result = publishNextGeneration(generationsDir, ({ current }) => {
    if (expectedControlEpoch !== undefined) {
      const currentEpoch = current?.epoch ?? null;
      if (currentEpoch !== expectedControlEpoch) {
        return { stop: true, status: 'stale', controlEpoch: currentEpoch };
      }
    }

    if (current) {
      if (current.record?.purpose === 'settled') {
        return { stop: true, status: 'settled', controlEpoch: current.epoch };
      }
      const released = readMarker(releaseMarkerPath(releasesDir, current.epoch)) !== null;
      if (!released) {
        const heartbeatFresh = typeof ttlMs === 'number' && now - current.record.acquiredAt <= ttlMs;
        if (heartbeatFresh) {
          return { stop: true, status: 'held', controlEpoch: current.epoch, holder: current.record.holder };
        }
        // Heartbeat expired (or no ttlMs given, meaning always attempt):
        // permitted to ATTEMPT reclaim. Only proven-dead identity actually
        // authorizes it (resolveHolderLiveness, H1) -- a live PID, or one
        // whose liveness cannot be disproven, remains HELD, full stop, no
        // matter how stale this generation looks.
        if (resolveHolderLiveness(current.record.holder) === 'held') {
          return { stop: true, status: 'held', controlEpoch: current.epoch, holder: current.record.holder };
        }
      }
    }

    return {
      record: {
        controlToken: crypto.randomUUID(),
        holder,
        purpose,
        acquiredAt: now,
      },
    };
  });

  if (!result.published) {
    return { status: result.status, controlEpoch: result.controlEpoch ?? null, holder: result.holder };
  }
  return { status: 'acquired', controlEpoch: result.epoch, controlToken: result.record.controlToken };
}

/**
 * Read-only: is this Run's current control generation still effectively
 * held? Same "released marker, then dead-holder proof" logic
 * `acquireRunControl`'s own reclaim decision applies, but with no write --
 * a caller that only needs to ASK, never to acquire (Phase 03 M1: deciding
 * whether admitting a brand-new attempt for an Assignment would spawn a
 * second worker racing an unsettled one), must never cause the side effect
 * of publishing a new generation into a DIFFERENT Run's own control ledger
 * just to peek at it.
 *
 * Returns `{held: false}` when there is no generation at all, or the
 * current one is released/its holder is provably dead (Phase 02 identity);
 * `{held: true, controlEpoch, holder}` otherwise -- alive, or liveness that
 * cannot be disproven, both read as "still held" (fail closed).
 */
export function inspectRunControl(runDir) {
  const { generationsDir, releasesDir } = controlDirs(runDir);
  const current = currentGeneration(generationsDir);
  if (!current) return { held: false };
  if (current.record?.purpose === 'settled') return { held: false, settled: true, controlEpoch: current.epoch };
  const released = readMarker(releaseMarkerPath(releasesDir, current.epoch)) !== null;
  if (released) return { held: false, controlEpoch: current.epoch };
  if (resolveHolderLiveness(current.record.holder) === 'dead') return { held: false, controlEpoch: current.epoch };
  return { held: true, controlEpoch: current.epoch, holder: current.record.holder };
}

/**
 * Commit authoritative settlement for a Run under its control ledger.
 *
 * Atomic CAS:
 * - Checks that { controlEpoch, controlToken } is the current generation in generationsDir.
 * - Publishes the next generation with purpose: 'settled', fencing any future controller.
 * - If current generation does not match or a newer controller has taken over, returns
 *   { status: 'superseded', controlEpoch: current?.epoch }.
 * - If already settled, returns { status: 'already-settled', controlEpoch: current?.epoch }.
 */
export function settleRunControl(runDir, { controlEpoch, controlToken, now = Date.now() } = {}) {
  const { generationsDir } = controlDirs(runDir);
  const result = publishNextGeneration(generationsDir, ({ current, nextEpoch }) => {
    if (!current || current.epoch !== controlEpoch || current.record.controlToken !== controlToken) {
      return { stop: true, status: 'superseded', controlEpoch: current?.epoch ?? null };
    }
    if (current.record.purpose === 'settled') {
      return { stop: true, status: 'already-settled', controlEpoch: current.epoch };
    }
    return {
      record: {
        controlToken,
        purpose: 'settled',
        settledEpoch: controlEpoch,
        acquiredAt: now,
      },
    };
  });

  if (!result.published) {
    return { status: result.status, controlEpoch: result.controlEpoch ?? null };
  }
  return { status: 'settled', controlEpoch: result.epoch };
}

/**
 * Release a held control token. Idempotent: releasing an already-released
 * epoch/token is a no-op, never an error, so a `finally` block can always
 * call this safely. `status: 'token-mismatch'`/`'unknown-generation'` means
 * this caller no longer names the generation it thinks it holds (e.g. it
 * was already superseded after PID-dead reclaim) -- never throws, so a
 * cleanup path is never blocked by its own staleness.
 */
export function releaseRunControl(runDir, { controlEpoch, controlToken, now = Date.now() } = {}) {
  const { generationsDir, releasesDir } = controlDirs(runDir);
  const record = parseJsonFile(path.join(generationsDir, generationFileName(controlEpoch)));
  if (record === null) return { status: 'unknown-generation' };
  if (record.controlToken !== controlToken) return { status: 'token-mismatch' };

  const outcome = publishMarkerOnce(releaseMarkerPath(releasesDir, controlEpoch), {
    controlEpoch,
    controlToken,
    releasedAt: now,
  });
  return { status: outcome.published ? 'released' : 'already-released' };
}

/**
 * Whether `{controlEpoch, controlToken}` is still the Run's current
 * control generation right now. Used to detect that an async adapter call
 * has outlived its logical control token: a caller starts an adapter I/O
 * under a token, and before committing that I/O's effect/result, calls this
 * to confirm nothing superseded it in the meantime. This function itself
 * never blocks or cancels anything -- it only answers the question; the
 * caller decides what to do with a `false` answer (typically: refuse to
 * commit, same as a stale-control-token settlement refusal).
 */
export function isRunControlCurrent(runDir, { controlEpoch, controlToken }) {
  const { generationsDir } = controlDirs(runDir);
  const current = currentGeneration(generationsDir);
  if (!current) return false;
  return current.epoch === controlEpoch && current.record.controlToken === controlToken;
}

// loop.mjs — the sequential runner loop (per D2/D3/D4/D5, A1): startup reap
// → frontier → anti-loop gate → claim → isolated worktree → dispatch →
// goal-check → propose/park/halt. One item at a time (A1), FIFO head first
// (A2), and inside the dispatch loop the RUNNER is the only writer through
// the store facade (per D3) — the worker's prompt forbids it from calling
// `fgos`, and nothing here ever trusts the worker's own report: the runner
// re-runs the item's `verify` itself in the worktree (goal-check).
//
// WRITE DISCIPLINE: every state mutation in this module goes through
// store.mjs's moveWork (the single write door) with an explicit
// `expectedStatus` (CAS). A CAS conflict on the runner's OWN write means
// someone else (a human operator, another process) raced it — classified
// `state-conflict`, and per the recovery matrix the runner never fights for
// the write: it cleans up its worktree (the finally below) and halts with
// the conflict exit code. It never overwrites blindly and never retries the
// write.
//
// WORKTREE LIFECYCLE: `removeWorktree` runs in a `finally` around EVERY
// per-item path — propose, retry, park, halt, and any throw — so no exit
// path leaks a checkout. The branch (`fgw/<id>`) always survives teardown:
// it is the durable D1-level proposal artifact (per D4). A retry never
// builds on a previous attempt's debris: each attempt gets a FRESH worktree
// directory checked out at the (reused) branch's current tip, then reset
// --hard to this item's own DISPATCH BASELINE (the branch tip captured on
// this item's first attempt, before any worker of its own ran) — not HEAD,
// which IS the prior attempt's own commit whenever that attempt committed
// before failing verify. The baseline preserves anything legitimately on
// the branch before this item's own dispatch (e.g. an earlier merged leaf,
// D3) while discarding only this item's own failed work.
//
// OUTPUT DISCIPLINE (security panel): worker stdout/stderr and verify
// output are surfaced on the console only (a tail, via `log`) — never
// persisted to any committed path. This module writes no files at all
// outside the store facade's own `.fgos/` writes.
// SUPERSEDED (D1, worker-dispatch-log) — narrowed, not repealed: worker
// stdout/stderr is now ALSO persisted to `.fgos/logs/` (git-ignored, per D4)
// via the sibling worker-log.mjs facade, so a launcher can recover what
// a worker did after the console tail scrolls past. The guarantee that
// actually mattered still holds exactly — worker output never lands in a
// committed/git-tracked path. Verify/goal-check output stays console-only
// (out of scope).
// LIVE LOG: a worker runs as a Unit run, which streams nothing back. The
// moment the run exists, the item's log gets one line naming it and where its
// stdout/stderr logs live (`.fgos/assignments/<unitRunId>/...`), so `tail -f`
// on the item's log points at the live output. The terminal block appended
// once dispatch settles (below) still carries the worker's full output.
//
// REPO ROOT: always derived from the caller's cwd (`git rev-parse
// --show-toplevel`), never from this file's own location — the runner
// operates on whatever repo it is invoked in, not on the repo that happens
// to contain its source.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import {
  listWork,
  moveWork,
  settleClaim,
  addWork,
